 @Test public void allBookIconEdgesAndPaletteMatchMartialWithDistinctGlyphsAndAliases()throws Exception{
  SkillIconCatalog icons=new SkillIconCatalog(h.c);SkillBook b=SkillBook.load(h.c);Bitmap ref=BitmapFactory.decodeStream(h.c.getAssets().open("skill-window/common-martial-frame-v253.png"));assertNotNull(ref);Set<Integer> palette=new HashSet<>();for(int y=0;y<31;y++)for(int x=0;x<31;x++)palette.add(ref.getPixel(x,y));Bitmap sheet=Bitmap.createBitmap(16*64,15*70,Bitmap.Config.ARGB_8888);sheet.eraseColor(0xff343b43);Canvas c=new Canvas(sheet);int count=0;Set<Integer> hashes=new HashSet<>();
  for(SkillBook.Entry e:b.entries())if(b.previewable(e.id)&&icons.has(e.id)){Bitmap image=icons.squareIcon(e.id);assertNotNull(e.id,image);int hash=1;for(int y=0;y<31;y++)for(int x=0;x<31;x++){int color=image.getPixel(x,y);if(x<3||x>=28||y<3||y>=28||Color.alpha(ref.getPixel(x,y))==0)assertEquals(e.id+" common background edge",ref.getPixel(x,y),color);else if(Color.alpha(color)>0)assertTrue(e.id+" martial colors",palette.contains(color));hash=31*hash+color;}hashes.add(hash);icons.drawSquare(c,e.id,new RectF(count%16*64,count/16*70,count%16*64+60,count/16*70+60));count++;}assertEquals("all204 identified source glyphs",204,count);assertTrue("glyph identities retained",hashes.size()>100);int missing=0;for(SkillBook.Entry e:b.entries())if(b.previewable(e.id)&&!icons.has(e.id)){Bitmap empty=Bitmap.createBitmap(31,31,Bitmap.Config.ARGB_8888);icons.drawBookBackground(new Canvas(empty),new RectF(0,0,31,31));for(int y=0;y<31;y++)for(int x=0;x<31;x++)if(x<3||x>=28||y<3||y>=28)assertEquals(e.id,ref.getPixel(x,y),empty.getPixel(x,y));missing++;}assertEquals("11 unresolved glyphs still use the same book background",11,missing);assertSame(icons.squareIcon("SK_무도가_001"),icons.squareIcon("SK_무도가_006"));assertSame(icons.squareIcon("SK_도적_001"),icons.squareIcon("SK_도적_007"));save(sheet,"all-book-icons");
 }
